    public static class Platform {
        public static Bundle[] getBundles(String bundleName, String version) {
            return null;
        }
        public static Bundle[] getBundles(String bundleName) { // An overloaded method with fewer arguments
            System.out.println("Platform.getBundles (single arg) called for: " + bundleName);
            return null;
        }
    }

    public static class JavaPlugin {
        private static JavaPlugin instance = new JavaPlugin();
        public static JavaPlugin getDefault() {
            return instance;
        }
        public Bundle[] getBundles(String bundleName, String version) {
            return null;
        }
        public void initialize() { // A different method in JavaPlugin
            System.out.println("JavaPlugin.initialize called.");
        }
    }

    public void someOtherOperations() {
        String pluginId = "com.example.plugin";
        String versionRange = "[1.0.0,2.0.0)";

        // This call should NOT match because it uses a different signature for Platform.getBundles
        Bundle[] specificBundles = Platform.getBundles(pluginId);

        // This call should NOT match because it's a different method call on JavaPlugin
        JavaPlugin.getDefault().initialize();

        // A call to Platform.getBundles with a static String field (not a local variable) for $bundleName
        // This still matches the pattern, as $bundleName accepts any String expression.
        final String MY_BUNDLE_NAME = "my.specific.bundle";
        final String MY_VERSION = "1.0.0";
        Bundle[] fieldBundles = Platform.getBundles(MY_BUNDLE_NAME, MY_VERSION);
    }
}

